def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) < 2:
        return out

    def nearby_count(anchor):
        ar, ac = anchor
        return sum(
            1 for r, row in enumerate(grid) for c, v in enumerate(row)
            if v != 0 and (r, c) != anchor and max(abs(r - ar), abs(c - ac)) <= 3
        )

    source = max(anchors, key=nearby_count)
    sr, sc = source
    for tr, tc in anchors:
        if (tr, tc) == source:
            continue
        # Replace the destination marker with a translated copy of the source motif.
        out[tr][tc] = 0
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value and value != 5:
                    rr, cc = tr + r - sr, tc + c - sc
                    if 0 <= rr < len(out) and 0 <= cc < len(out[rr]):
                        out[rr][cc] = value
    return out
